INSERT INTO package_questions (id, package_id, question_json, status, order_index) VALUES ('15c58450-6991-4d2e-97b7-b44454b9c9e9', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente de 38 anos, em tratamento regular para tuberculose pulmonar há 3 meses (término da fase de ataque), apresenta melhora clínica significativa e baciloscopias negativas no 1º e 2º meses. No entanto, o exame do 3º mês resultou em: ''Baciloscopia de Escarro: Positiva (1+)''. O paciente nega tosse ou febre. Qual o fenômeno imunológico que pode explicar este achado em um paciente que vinha em melhora progressiva?", "options": {"a": "Eliminação de bacilos mortos (bacilos persistentes não viáveis), o que não caracteriza necessariamente falência do tratamento.", "b": "Resistência secundária adquirida à Pirazinamida puramente motivada pelo estresse metabólico.", "c": "Erro laboratorial mandatório, pois é impossível ter baciloscopia positiva após 2 negativas.", "d": "Aparecimento de uma nova caverna pulmonar causada pelo ''efeito paradoxal'' das vitaminas do complexo B.", "e": "Infecção por micobactéria não tuberculosa (MNT) oportunista pela cura da TB primária."}, "answer": "a", "rationale": "Em alguns pacientes, conforme as cavidades pulmonares ''limpam'' e se consolidam, pode haver a expulsão ocasional de restos celulares e bacilos mortos (ou fragmentos de DNA) que são detectados pela baciloscopia (coloração de Ziehl-Neelsen) ou TRM-TB. Se o paciente está clinicamente bem e as culturas forem negativas, esse achado isolado não deve ser interpretado como falha. No entanto, exige monitoramento rigoroso e repetição do exame.", "option_rationales": {"a": "Correta. Fenômeno de ''clareamento'' cavitário.", "b": "Incorreta. A resistência secundária não se manifesta clinicamente como ''melhora total''.", "c": "Incorreta. Embora o erro possa ocorrer, há uma base biológica para este achado.", "d": "Incorreta. Não existe tal efeito paradoxal descrito com vitaminas.", "e": "Incorreta. MNTs não ''substituem'' a TB desta forma e não seriam a primeira hipótese."}, "difficulty": "media", "subspecialty": "Pneumologia", "subject": "Tuberculose", "tags": ["Fisiopatologia", "Monitoramento", "Baciloscopia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 50), ('21e37275-a89d-457b-b219-b5348ccf1fb9', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A Tuberculose Pericárdica é uma das formas mais graves de tuberculose extrapulmonar. Qual a complicação crônica mais temida desta condição e qual medicamento, se usado precocemente, pode reduzir sua incidência?", "options": {"a": "Pericardite Constritiva; uso de Prednisona (corticosteroides).", "b": "Tamponamento cardíaco agudo; uso de Digoxina.", "c": "Infarto agudo do miocárdio; uso de Aspirina.", "d": "Prolapso de valva mitral; uso de Penicilina benzatina.", "e": "Fibrilação atrial paroxística; uso de Varfarina."}, "answer": "a", "rationale": "A inflamação crônica causada pelo M. tuberculosis no pericárdio leva à deposição de fibrina, espessamento e posterior calcificação das camadas pericárdicas. Isso resulta em pericardite constritiva (o ''coração em couraça''), que impede o enchimento diastólico. O uso de corticoides (Prednisona) associado ao esquema RIPE ajuda a modular a resposta inflamatória e reduzir a formação de cicatrizes fibróticas, diminuindo o risco de constrição.", "option_rationales": {"a": "Correta. Complicação e prevenção clássica na TB cardíaca.", "b": "Incorreta. O tamponamento é uma complicação aguda (efusiva), não crônica (fibrosa).", "c": "Incorreta. A TB não atinge as coronárias desta maneira direta.", "d": "Incorreta. Isso descreve sequelas de febre reumática.", "e": "Incorreta. Arritmias podem ocorrer, mas a constrição é a sequela estrutural viga mestra da doença."}, "difficulty": "media", "subspecialty": "Cardiologia", "subject": "Tuberculose", "tags": ["TB Pericárdica", "Cardiologia", "Corticosteroides", "Prevenção"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 51), ('3da6b778-8fe1-4bed-91ec-5eae10e18331', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Uma enfermeira de 28 anos, gestante (18 semanas), foi exposta a um paciente com tuberculose pulmonar bacilífera. Ela nunca teve TB e sua PPD de admissão (há 1 ano) era 0 mm. Realizado novo PPD agora que resultou 15 mm. RX de tórax normal e assintomática. Qual a melhor conduta para a gestante?", "options": {"a": "Iniciar o Tratamento Preventivo da TB (TPTB) com Isoniazida ou Rifampicina imediatamente; a gestação NÃO é contraindicação para o tratamento de infecção latente.", "b": "Aguardar o término da gestação e do aleitamento para tratar a ILTB.", "c": "Interromper a gestação por risco de teratogenicidade dos fármacos da TB.", "d": "Indicar apenas vitamina B6 (Piridoxina) sem os antibióticos, pois o corpo grávido se protege sozinho.", "e": "Realizar abortamento terapêutico imediato, pois a mãe transmitirá a TB latente via placenta."}, "answer": "a", "rationale": "Gestantes têm o mesmo risco de adoecimento por TB que a população geral e, se adoecerem, a doença pode ser grave para o feto (baixo peso, prematuridade). A conversão tuberculínica recente indica infecção aguda. As drogas usadas no TPTB (Isoniazida e Rifampicina) são seguras na gestação. Portanto, o tratamento deve ser iniciado com suplementação obrigatória de Piridoxina (B6) para prevenir neuropatia na mãe e no feto.", "option_rationales": {"a": "Correta. Protocolo de ILTB em Gestantes atualizado.", "b": "Incorreta. O adiamento aumenta o risco de a gestante adoecer durante o período de maior vulnerabilidade (puerpério).", "c": "Incorreta. As drogas de primeira linha são categoria B/C e amplamente usadas com segurança.", "d": "Incorreta. A vitamina previne efeitos colaterais, mas não trata o bacilo.", "e": "Incorreta. A TB latente não ultrapassa a placenta e não existe indicação de interrupção de gravidez por TB."}, "difficulty": "media", "subspecialty": "Obstetrícia", "subject": "Tuberculose", "tags": ["Gestação", "ILTB", "Infectologia", "Saúde da Mulher"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 52), ('e1f46905-9742-467b-9692-23d7a73f8514', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente está tratando TB há 15 dias e apresenta prurido generalizado e manchas vermelhas (exantema morbiliforme) sem febre ou sinais de gravidade (sinal de Nikolsky negativo). Qual o manejo escalonado correto sugerido pelo Ministério da Saúde para reações cutâneas leves/moderadas?", "options": {"a": "Suspender todas as drogas até a regressão do exantema e, após, reintroduzir uma a uma começando pela Rifampicina (fármaco com menor chance de causar alergia grave).", "b": "Manter o tratamento e prescrever apenas hidratante corporal.", "c": "Suspender apenas a Isoniazida e manter o restante do tratamento por 1 ano.", "d": "Trocar por Estreptomicina injetável para o resto da vida.", "e": "Internar o paciente e realizar plasmaférese de urgência."}, "answer": "a", "rationale": "Em casos de farmacodermia leve a moderada, o protocolo é: 1) Suspender todas as drogas (R-I-P-E); 2) Aguardar o desaparecimento das lesões; 3) Reintroduzir as drogas sequencialmente para identificar o culpado: Rifampicina (3-7 dias de teste), Isoniazida (3-7 dias), Etambutol (3-7 dias) e, por último, a Pirazinamida (frequente culpada por alergias). Se a reação for grave (ex: Stevens-Johnson), as drogas não devem ser reintroduzidas.", "option_rationales": {"a": "Correta. Protocolo de reintrodução sequencial padrão.", "b": "Incorreta. Se houver alergia sistêmica, manter a droga pode levar à anafilaxia ou reações bolhosas graves.", "c": "Incorreta. Não se retira uma droga sem saber se ela é a causa.", "d": "Incorreta. A conduta é desproporcional e a estreptomicina também pode causar alergia.", "e": "Incorreta. Medidas de suporte são suficientes para casos leves após suspensão da droga."}, "difficulty": "media", "subspecialty": "Dermatologia", "subject": "Tuberculose", "tags": ["Farmacodermia", "Alergia", "Manejo", "Enfermagem"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 53), ('53b8390f-8f70-4010-967b-d54fe3b00b0d', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A Tuberculose de Orofaringe e Laringe é considerada uma das formas mais contagiosas da doença. Qual o sintoma cardinal da tuberculose laríngea que deve alertar o clínico para o diagnóstico em um paciente com tosse crônica?", "options": {"a": "Disfonia (rouquidão) progressiva e dolorosa.", "b": "Perda total da audição bilateral súbita.", "c": "Aumentos de volume das glândulas parótidas (Sialonose).", "d": "Gengivorragia maciça espontânea.", "e": "Odinofagia profunda que impede a deglutição de sólidos apenas."}, "answer": "a", "rationale": "A TB laríngea é quase sempre secundária à TB pulmonar (os bacilos expectorados ''banham'' as cordas vocais). O sintoma mais comum é a rouquidão (disfonia) e a dor ao falar/deglutir (odinofagia laríngea). Devido à alta carga bacilar e à aerolização pela fala, esses pacientes são extremamente bacilíferos, exigindo isolamento respiratório rigoroso.", "option_rationales": {"a": "Correta. Sintoma guia para TB de vias aéreas superiores.", "b": "Incorreta. Associado a otite média por TB ou ototoxicidade de drogas.", "c": "Incorreta. Sialonose é comum em parotidite viral ou sarcoidose.", "d": "Incorreta. A gengivite por TB é rara e não se manifesta tipicamente por hemorragia maciça isolada.", "e": "Incorreta. A dor costuma ser tanto para sólidos quanto para líquidos e a disfonia é o marco principal."}, "difficulty": "media", "subspecialty": "Otorrinolaringologia", "subject": "Tuberculose", "tags": ["Otorrinolaringologia", "Disfonia", "Contagiosidade", "Higiene"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 54), ('f831f1b0-120f-4edf-87f8-2f3335f0dc85', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um detento de 45 anos iniciou tratamento para TB com esquema RIPE. Após 3 meses, ele é transferido para o regime semiaberto e deixa de comparecer ao posto de saúde. Por quanto tempo de interrupção contínua um paciente deve ser considerado como tendo ''abandonado'' o tratamento no programa de controle da tuberculose?", "options": {"a": "30 dias ou mais após a data prevista para o retorno.", "b": "7 dias corridos após a falta à consulta.", "c": "6 meses, correspondendo a um curso completo.", "d": "Apenas se ele formalizar por escrito que não quer mais tomar os remédios.", "e": "24 horas de atraso na dose do Tratamento Diretamente Observado (TDO)."}, "answer": "a", "rationale": "Definição de Abandono (Ministério da Saúde): Considera-se abandono o caso em que o paciente, após iniciar o tratamento, deixa de comparecer à unidade de saúde (ou de receber a medicação no TDO) por 30 dias consecutivos ou mais. O abandono é um dos maiores desafios para a cura do paciente e para a saúde coletiva (risco de resistência).", "option_rationales": {"a": "Correta. Definição epidemiológica operacional.", "b": "Incorreta. 7 dias é considerado falta; busca ativa deve ser iniciada, mas ainda não é ''abandono'' oficial no sistema.", "c": "Incorreta. Seria tempo demais para esperar antes de tomar uma medida de vigilância.", "d": "Incorreta. A maioria dos abandonos é silenciosa e sem justificativa formal.", "e": "Incorreta. Seria impossível gerir o programa com um critério de 24h para abandono."}, "difficulty": "facil", "subspecialty": "Saúde Pública", "subject": "Tuberculose", "tags": ["Vigilância", "Abandono", "Fluxo", "Gestão"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 55), ('52b1505c-1b32-45f0-b9f8-4536a9ea9a55', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A Tuberculose Miliar pode evoluir com Síndrome do Desconforto Respiratório Agudo (SDRA) e falência de múltiplos órgãos. Qual o exame complementar que frequentemente demonstra a gravidade da disseminação hematogênica na medula óssea desses pacientes?", "options": {"a": "Mielograma ou Biópsia de medula óssea, evidenciando granulomas caseosos.", "b": "Dosagem de Vitamina B12 sérica.", "c": "Conteúdo de ferritina no líquor.", "d": "Avaliação de fragilidade osmótica eritrocitária.", "e": "Cintilografia óssea com tecnécio."}, "answer": "a", "rationale": "A TB miliar atinge órgãos ricos em filtros reticuloendoteliais, sendo a medula óssea um dos principais alvos. A biópsia de medula é extremamente útil em casos de febre de origem indeterminada, podendo demonstrar os granulomas típicos (caséolo) e permitir o isolamento do bacilo antes mesmo dos exames de escarro (que podem ser negativos na forma puramente hematogênica).", "option_rationales": {"a": "Correta. Método diagnóstico para TB disseminada.", "b": "Incorreta. A B12 avalia anemias carenciais, sem relação específica diagnóstica com a TB.", "c": "Incorreta. A ferritina é marcador inflamatório sérico e não faz parte do rastreio de TB no líquor.", "d": "Incorreta. Usado na investigação de esferocitose hereditária.", "e": "Incorreta. A cintilografia detecta áreas de hipermetabolismo ósseo, mas não diferencia TB de metástases ou infecções piogênicas."}, "difficulty": "media", "subspecialty": "Hematologia", "subject": "Tuberculose", "tags": ["TB Miliar", "Medula Óssea", "Hematologia", "Biópsia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 56), ('542b2573-fd9b-4eb4-bf14-fc51b15aa420', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente de 58 anos, morador de área rural, apresenta febre, perda de peso e o RX de tórax com cavitação em ápice pulmonar. Ele relata o costume de ''pastar'' ou mastigar gravetos e capim. Além de Tuberculose, qual o principal diagnóstico diferencial desta síndrome cavitária, considerando a exposição e a localização geográfica?", "options": {"a": "Paracoccidioidomicose (Micose Sul-Americana).", "b": "Asbestos pulmonar pela poeira da estrada.", "c": "Histoplasmose epidêmica (doença das cavernas).", "d": "Sarcoidose estádio IV.", "e": "Silicose aguda por moagem de grãos."}, "answer": "a", "rationale": "A Paracoccidioidomicose (PCM) é frequentemente confundida com a Tuberculose. Ambas atingem o parênquima pulmonar com infiltrados e cavitações, causam sintomas constitucionais (febre/emagrecimento) e linfonodomegalias. O hábito de mastigar vegetais (onde o fungo reside no solo) é um dado epidemiológico clássico. O diagnóstico diferencial é fundamental, pois o tratamento da PCM envolve sulfonamidas ou derivados imidazólicos (ex: Itraconazol), enquanto o da TB envolve antibióticos específicos.", "option_rationales": {"a": "Correta. Principal diagnóstico diferencial micológico da TB no Brasil.", "b": "Incorreta. Causa fibrose em bases, sem síndrome febril aguda/subaguda típica.", "c": "Incorreta. Associada a fezes de morcegos em cavernas/galinheiros.", "d": "Incorreta. Doença granulomatosa sistêmica idiopática; menos provável com histórico rural e hábito mastigatório.", "e": "Incorreta. Exposição à sílica envolve mineração ou jateamento de areia."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["PCM", "Diagnóstico Diferencial", "Infectologia", "Brasil"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 57), ('4cba0065-5f06-4528-ade9-e8fb66136eba', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a orientação correta quanto ao tempo de isolamento respiratório (precaução para aerossóis) para um paciente com Tuberculose Pulmonar sensível que está sob tratamento adequado com o esquema RIPE e apresenta boa adesão?", "options": {"a": "Geralmente 15 dias após o início do tratamento efetivo, desde que haja melhora clínica, pois a carga bacilar na via aérea cai drasticamente neste período.", "b": "Até que o tratamento complete 6 meses.", "c": "O isolamento não é necessário em nenhum momento, apenas o uso de máscara cirúrgica pelo médico.", "d": "Até que o PPD (teste cutâneo) negative.", "e": "Vitalício para contato com crianças e idosos."}, "answer": "a", "rationale": "Após 14 a 15 dias de tratamento correto com Rifampicina (altamente bactericida), a maioria dos pacientes com TB sensível deixa de ser infectante, pois os bacilos remanescentes na via aérea estão inviabilizados para transmissão. No entanto, se houver suspeita de resistência ou o paciente estiver em ambiente hospitalar crítico, o isolamento deve ser mantido até a negativação definitiva das baciloscopias.", "option_rationales": {"a": "Correta. Critério operacional de desisolamento ambulatorial/hospitalar.", "b": "Incorreta. Seria inviável manter o isolamento por 6 meses para todos os pacientes.", "c": "Incorreta. A transmissibilidade no início (fase pré-tratamento) é real e perigosa.", "d": "Incorreta. O PPD raramente negativa e não serve para monitorar transmissibilidade ou cura.", "e": "Incorreta. O contagio cessa com o tratamento resolutivo."}, "difficulty": "facil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Biossegurança", "Isolamento", "Transmissibilidade", "Epidemiologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 58), ('8db852cd-a3fb-4a18-85b1-22e6c0230f72', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente de 40 anos, com TB pulmonar, apresenta quadro de tonturas, náuseas e dificuldades na marcha (desequilíbrio). Ao exame físico, nota-se nistagmo horizontal e alteração no teste de Romberg. Qual fármaco, tipicamente usado em esquemas de segunda linha ou retratamento, é o principal suspeito deste efeito ototóxico vestibular?", "options": {"a": "Estreptomicina (ou outros aminoglicosídeos).", "b": "Levofloxacino.", "c": "Bedaquilina.", "d": "Linezolida.", "e": "Clofazimina."}, "answer": "a", "rationale": "A Estreptomicina é um aminoglicosídeo injetável que tem como principal toxicidade a lesão do VIII par craniano (nervo vestibulococlear). Pode causar tanto perda auditiva (toxicidade coclear) quanto tontura/vertigem (toxicidade vestibular). O idoso e o renal crônico são mais susceptíveis. Por isso, as drogas injetáveis foram retiradas da primeira linha de tratamento.", "option_rationales": {"a": "Correta. Efeito adverso clássico do grupo dos aminoglicosídeos.", "b": "Incorreta. Causa rotura de tendões e distúrbios do SNC (insônia/tremores), não ototoxicidade direta.", "c": "Incorreta. Aumenta o intervalo QT no ECG.", "d": "Incorreta. Causa neurite óptica e plaquetopenia periférica.", "e": "Incorreta. Causa pigmentação acastanhada da pele."}, "difficulty": "media", "subspecialty": "Neurologia", "subject": "Tuberculose", "tags": ["Ototoxicidade", "Estreptomicina", "Efeitos Adversos", "Auditivo"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 59), ('ccbd16d1-e516-4e49-a4fd-0e42a2454cc6', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Como deve ser feita a investigação de contatos intradomiciliares de um caso índice de Tuberculose Pulmonar Bacilífera?", "options": {"a": "Todos os contatos (independentemente da presença de sintomas) devem ser avaliados com anamnese, RX de tórax e teste de infecção latente (PPD ou IGRA).", "b": "Apenas os contatos que estiverem tossindo sangue devem ser avaliados.", "c": "Somente crianças menores de 5 anos devem ser investigadas.", "d": "Deve-se tratar preventivamente todos os contatos com o esquema RIPE antes mesmo de fazer exames.", "e": "Os contatos só precisam se afastar do paciente por 15 dias, sem necessidade de exames."}, "answer": "a", "rationale": "O controle de contatos visa: 1) Identificar casos de TB doença escondidos (busca ativa); 2) Identificar infecção latente (ILTB) para tratamento preventivo. Portanto, a avaliação deve ser universal no domicílio do paciente índice bacilífero.", "option_rationales": {"a": "Correta. Norma de vigilância epidemiológica fundamental.", "b": "Incorreta. Muitos casos de TB ativa têm tosse seca ou sintomas vagos.", "c": "Incorreta. Adultos, idosos e imunodeprimidos do domicílio também têm alto risco.", "d": "Incorreta. Tratamento (esquema RIPE) exige diagnóstico de doença; a prevenção (monoterapia) exige exclusão de doença.", "e": "Incorreta. A conduta é passiva e ignora o risco de infecção já estabelecida no grupo."}, "difficulty": "facil", "subspecialty": "Saúde Pública", "subject": "Tuberculose", "tags": ["Vigilância", "Contatos", "Saúde da Família", "Fluxo"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 60), ('26cea077-db0c-40cb-b26a-3be662c1a55a', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Recentemente, o Ministério da Saúde do Brasil recomenda a Rifapentina (associada à Isoniazida - esquema 3HP) como uma opção para o tratamento preventivo da Tuberculose (TPTB). Qual a principal vantagem logística do esquema 3HP em comparação à Isoniazida isolada (6 ou 9 meses)?", "options": {"a": "Duração muito menor (apenas 12 doses semanais em 3 meses) e maior taxa de adesão.", "b": "Custo 100 vezes menor em farmácias populares.", "c": "Pode ser administrada via inalatória através de nebulização.", "d": "Elimina a necessidade de suplementação com Vitamina B6.", "e": "Causa coloração verde na urina, facilitando o controle visual do médico."}, "answer": "a", "rationale": "O esquema 3HP (3 meses de Rifapentina + Isoniazida semanal) revolucionou o tratamento da ILTB. Por ser curto e exigir apenas uma tomada semanal, a adesão é muito superior aos esquemas de 6 a 9 meses de doses diárias de Isoniazida. É a escolha preferencial para contatos e pessoas vivendo com HIV com boa contagem de CD4.", "option_rationales": {"a": "Correta. Benefício logístico e terapêutico moderno.", "b": "Incorreta. A Rifapentina é, na verdade, uma droga mais cara por dose unitária, mas compensa pela redução de danos e aumento da cura latente.", "c": "Incorreta. A via é puramente oral.", "d": "Incorreta. A Isoniazida continua presente, exigindo B6 se houver fatores de risco.", "e": "Incorreta. A Rifapentina, como a Rifampicina, colore os fluidos de vermelho/laranja, não verde."}, "difficulty": "media", "subspecialty": "Saúde Pública", "subject": "Tuberculose", "tags": ["ILTB", "3HP", "Adesão", "Novas Tecnologias"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 61), ('c3e1d2eb-292f-4dbb-9c61-d4292def1b08', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente de 48 anos com história de silicose ocupacional (ex-minerador) procura o ambulatório por febre, perda ponderal e RX com novos infiltrados cavitários. Por que a Tuberculose é tão frequente em pacientes com Silicose (Síndrome de Silicotuberculose)?", "options": {"a": "A sílica ingerida pelos macrófagos alveolares causa sua necrose e impede a contenção adequada do M. tuberculosis.", "b": "O bacilo da TB se alimenta quimicamente do dióxido de silício presente nos pulmões.", "c": "A vacina BCG é neutralizada pelas partículas de areia no interstício pulmonar.", "d": "Pacientes com silicose costumam ter alergia severa à Isoniazida.", "e": "Não há relação estatística entre as duas condições; é apenas uma coincidência epidemiológica."}, "answer": "a", "rationale": "A sílica é citotóxica para os macrófagos alveolares. O macrófago é a célula viga mestra da defesa contra o bacilo de Koch. Quando os macrófagos estão ''ocupados'' ou destruídos pelo processamento da sílica, a imunidade local pulmonar fica devastada, permitindo que qualquer bacilo inalado ou latente se prolifere descontroladamente. Pacientes silicoticos têm risco dezenas de vezes maior de desenvolver TB que a população geral.", "option_rationales": {"a": "Correta. Explicação fisiopatológica clássica da pneumoconiose e infecção.", "b": "Incorreta. O bacilo é quimio-heterotrófico e se alimenta de substâncias orgânicas do hospedeiro.", "c": "Incorreta. A BCG é uma vacina neonatal e sua ação imune é sistêmica/celular, não física neutralizável por poeira.", "d": "Incorreta. Não existe tal associação farmacológica fixa.", "e": "Incorreta. A associação é fortíssima e descrita em todos os manuais de medicina do trabalho."}, "difficulty": "media", "subspecialty": "Pneumologia", "subject": "Tuberculose", "tags": ["Silicose", "Pneumoconiose", "Saúde Ocupacional", "Imunologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 62), ('73b1ddb8-18a7-435b-9cb8-98124d7e58a8', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A Tuberculose Urogenital pode causar uma complicação radiológica característica chamada de ''rim mastigado'' (masticated kidney) ou ''autonefrectomia''. O que isso representa?", "options": {"a": "Um rim destruído por calcificações e retrações cicatriciais extensas, tornando-se não funcional.", "b": "Um rim com múltiplos tumores malignos síncronos causados pela TB.", "c": "Uma infestação do sistema coletor por larvas de insetos atraídas pelo pus da TB.", "d": "Um rim transplantado que sofre rejeição hiperaguda pela TB latente do doador.", "e": "A presença de cálculos de struvita gigantes ocupando todo o parênquima."}, "answer": "a", "rationale": "A TB causa inflamação destrutiva crônica (necrose de caseificação) que atinge os cálices, a pelve e o parênquima renal. Com a evolução e a tentativa de cura por fibrose e calcificação, o rim se retrai e se torna um bloco de cálcio e tecido cicatricial sem função excretora (autonefrectomia). Na radiologia/TC, as imagens dessas áreas de destruição irregular lembram um órgão ''mastigado''.", "option_rationales": {"a": "Correta. Achado de imagem patognomônico de TB renal tardia.", "b": "Incorreta. A TB não é oncogênica desta forma.", "c": "Incorreta. Absurdo biológico.", "d": "Incorreta. Não tem relação direta com o termo ''rim mastigado''.", "e": "Incorreta. Cáclulos de estruvita sugerem infecção por Proteus e não TB."}, "difficulty": "media", "subspecialty": "Urologia", "subject": "Tuberculose", "tags": ["TB Renal", "Radiologia", "Autonefrectomia", "Urologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 63), ('748810ac-013e-4770-8fb9-4d59756c9e31', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente de 41 anos está no 5º mês de tratamento (fase de manutenção) para TB pulmonar. Ele relata ao médico que parou de sentir o gosto e o cheiro dos alimentos e que tem sentido tremores leves nas mãos. Qual o manejo correto desse possível efeito colateral neurológico central?", "options": {"a": "Investigar toxicidade pela Isoniazida; administrar Piridoxina (B6) e, se não houver melhora, considerar suspensão da droga.", "b": "Suspender a Rifampicina imediatamente pois causa ''anosmia química''.", "c": "Diagnosticar COVID-19 e colocar em quarentena forçada.", "d": "Não são efeitos esperados das drogas da TB; investigar tumor de tronco cerebral.", "e": "Orientar que o cheiro forte da Pirazinamida causa saturação olfativa passageira."}, "answer": "a", "rationale": "Embora a neuropatia periférica seja mais comum, a Isoniazida pode causar efeitos no SNC (tremores, irritabilidade, convulsões, distúrbios da memória e, mais raramente, distúrbios sensitivos centrais). A base do manejo é a reposição de Vitamina B6, que ajuda a ''estabilizar'' o metabolismo neuronal afetado pela droga.", "option_rationales": {"a": "Correta. Associação clássica da toxicidade central da isoniazida.", "b": "Incorreta. Rifampicina não tem esse perfil de neurotoxicidade.", "c": "Incorreta. Embora COVID cause anosmia, os tremores e o contexto do tratamento de TB tornam a farmacotoxicologia a primeira hipótese.", "d": "Incorreta. São efeitos descritos na bula e na literatura sobre a droga.", "e": "Incorreta. Não existe esta saturação mecânica descrita clinicamente para a pirazinamida."}, "difficulty": "media", "subspecialty": "Neurologia", "subject": "Tuberculose", "tags": ["Efeitos Adversos", "Isoniazida", "SNC", "B6"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 64), ('e384d411-d4d5-4563-b408-879c5cccbfc4', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Em pacientes com Tuberculose Ocular, qual a manifestação mais frequente observada no exame de fundo de olho?", "options": {"a": "Coroidite tuberculosa (presença de tubérculos de coroide, infiltrados branco-amarelados).", "b": "Descolamento de retina exsudativo maciço.", "c": "Oclusão de artéria central da retina.", "d": "Cristais de colesterol na fóvea (Mancha de Cherry-red).", "e": "Hemorragia vítrea em ''chama de vela''."}, "answer": "a", "rationale": "A TB disseminada pode atingir a coroide (a camada vascular do olho). Os ''tubérculos de coroide'' são granulomas visíveis ao oftalmoscópio como pequenas placas amareladas e elevadas. Sua presença é um forte indicativo de disseminação hematogênica (TB biliar ou miliar).", "option_rationales": {"a": "Correta. Marco diagnóstico da TB ocular.", "b": "Incorreta. Pode ocorrer em formas severas, mas não é a mais ''frequente''.", "c": "Incorreta. Característico de fenômenos embólicos agudos.", "d": "Incorreta. Mancha de Cherry-red é associada a doenças metabólicas ou oclusão arterial.", "e": "Incorreta. Hemorragia em chama de vela é comum em retinopatia hipertensiva ou diabética."}, "difficulty": "media", "subspecialty": "Oftalmologia", "subject": "Tuberculose", "tags": ["Coroidite", "Oftalmologia", "Tubérculo de Coroide", "Miliar"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 65), ('eeb2a1e7-c501-49e3-961b-6a602e5478ba', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual o principal critério para a interrupção do isolamento hospitalar de um paciente com Tuberculose em sistema de pressão negativa e filtros HEPA?", "options": {"a": "Melhora clínica clara do paciente e pelo menos duas (idealmente três) baciloscopias de escarro negativas, coletadas em dias diferentes, sob tratamento adequado.", "b": "O tratamento completar 48 horas.", "c": "O paciente prometer que usará máscara cirúrgica no corredor.", "d": "O teste de PPD (feito na alta) ser negativo.", "e": "A família solicitar a alta por motivos religiosos."}, "answer": "a", "rationale": "Diferente do isolamento domiciliar (onde 15 dias de tratamento costumam bastar para o desisolamento operacional), o ambiente hospitalar exige critérios mais rígidos por conter outros pacientes vulneráveis. A demonstração de negativas em série (baciloscopia negativa) é o padrão-ouro de segurança para suspender a precaução para aerossóis.", "option_rationales": {"a": "Correta. Protocolo de segurança hospitalar.", "b": "Incorreta. 48h é tempo insuficiente para assepsia da via aérea.", "c": "Incorreta. Comprometimento verbal não tem valor biológico de segurança.", "d": "Incorreta. PPD não serve para alta ou desisolamento.", "e": "Incorreta. Motivos sociais ou religiosos não suplantam o risco de infecção hospitalar massiva."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Biossegurança", "Isolamento", "Infectologia", "Gestão Hospitalar"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 66), ('d67cc039-3ce2-4e9c-9703-1b4bc12eae58', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente de 32 anos apresenta infertilidade primária há 2 anos. Antecedente pessoal de ''frialdade abdmoninal'' e ascite leve na adolescência tratada como ''problemas de estômago''. Histerossalpingografia atual revela trompas obstruídas e com aspecto de ''contas de rosário'' ou ''trompas em cachimbo''. Qual a principal hipótese diagnóstica?", "options": {"a": "Salpingite Tuberculosa (TB Genital feminina).", "b": "Endometriose profunda severa.", "c": "Síndrome dos Ovários Policísticos (SOP).", "d": "Infecção por Clamídia aguda.", "e": "Síndrome de Asherman pós-curetagem."}, "answer": "a", "rationale": "A TB genital é uma causa silenciosa e frequente de infertilidade em áreas endêmicas. O bacilo atinge as trompas (salpingite) via hematogênica, causando destruição da mucosa e áreas de estenose e dilatação (contas de rosário). Frequentemente é sequela de uma TB peritoneal ocorrida anos antes. O diagnóstico exige biópsia de endométrio ou cultura de fluxo menstrual.", "option_rationales": {"a": "Correta. Causa de esterilidade tubária clássica.", "b": "Incorreta. Endometriose causa aderências, mas o padrão de ''rosário'' nas trompas é muito sugestivo de TB ou DIPA crônica.", "c": "Incorreta. SOP é uma desordem anovulatória, não anatômica tubária.", "d": "Incorreta. A clamídia causa obstrução, mas raramente com este histórico de doença sistêmica pregressa.", "e": "Incorreta. Asherman ocorre após traumas uterinos (leves), não atingindo as trompas desta maneira."}, "difficulty": "media", "subspecialty": "Ginecologia", "subject": "Tuberculose", "tags": ["Infertilidade", "Sinal do Rosário", "Ginecologia", "Infectologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 67), ('731cf094-5734-4959-a399-636f932c5ce8', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A Tuberculose Mamária é uma apresentação rara. Qual o diagnóstico diferencial mais importante na prática clínica, especialmente em mulheres com mais de 40 anos?", "options": {"a": "Câncer de Mama.", "b": "Prolactinoma.", "c": "Ectasia ductal.", "d": "Mastite puerperal comum.", "e": "Lipoma intramamário."}, "answer": "a", "rationale": "A TB mamária se manifesta como um nódulo endurecido, às vezes com retração da pele ou fístulas que drenam material purulento/caseoso. Por ser um nódulo fixo e de crescimento progressivo, simula perfeitamente um carcinoma mamário. A biópsia é obrigatória para diferenciar as duas entidades.", "option_rationales": {"a": "Correta. Principal ''grande simulador'' no tecido mamário.", "b": "Incorreta. Prolactinoma causa galactorreia bilateral, sem nódulos mamários inflamatórios.", "c": "Incorreta. Ectasia ductal causa descarga papilar, sem formação de fístulas caseosas sistêmicas.", "d": "Incorreta. Ocorre no período da amamentação e é uma infecção por Gram-positivos aguda.", "e": "Incorreta. Lipoma é macio, móvel e indolor."}, "difficulty": "media", "subspecialty": "Mastologia", "subject": "Tuberculose", "tags": ["Mastologia", "Oncologia", "Diagnóstico Diferencial", "Nódulos"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 68), ('5f0b0cc8-095d-4dd4-8a01-1ed8f73ad923', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Em pacientes com Tuberculose e uso de Dolutegravir (DTG) para HIV, dobramos a dose do DTG para 50 mg 12/12h. Quando o paciente termina o tratamento da TB e para de usar a Rifampicina, por quanto tempo ainda se deve manter a dose dobrada do Dolutegravir?", "options": {"a": "Duas semanas após a última dose de Rifampicina, pois a indução enzimática demora este tempo para dissipar.", "b": "Pode voltar para a dose normal no dia seguinte.", "c": "Deve-se manter a dose dobrada pelo resto da vida.", "d": "Pelo menos por 6 meses para garantir que não haja ''efeito rebote''.", "e": "Até que a carga viral do HIV negative novamente."}, "answer": "a", "rationale": "A indução enzimática do citocromo P450 pela Rifampicina é potente e persistente. Mesmo após a interrupção da droga, as enzimas hepáticas ''induzidas'' permanecem ativas por cerca de 10 a 14 dias até serem degradadas naturalmente. Portanto, para manter níveis seguros de Dolutegravir, mantém-se a dose dobrada por 2 semanas após o fim do esquema RIPE.", "option_rationales": {"a": "Correta. Orientação farmacocinética de precisão para TB-HIV.", "b": "Incorreta. Se baixar no dia seguinte, o DTG será degradado rapidamente pelas enzimas remanescentes.", "c": "Incorreta. Desnecessário e aumenta o risco de efeitos colaterais do DTG.", "d": "Incorreta. Tempo excessivamente longo.", "e": "Incorreta. O critério é baseado na meia-vida das enzimas citocromais, não na carga viral diretamente."}, "difficulty": "dificil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Interações", "Dolutegravir", "Rifampicina", "Farmacologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 69), ('50329b6d-663c-4f5f-b979-8dff4162a597', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a principal complicação metabólica da Tuberculose Adrenal (Doença de Addison por TB)?", "options": {"a": "Insuficiência adrenal primária (hipocortisolismo e hipoaldosteronismo), causando hiponatremia, hipercalemia e hipotensão.", "b": "Síndrome de Cushing por hipercortisolismo reacional.", "c": "Diabetes Insipidus central.", "d": "Hipertireoidismo severo.", "e": "Hipercalcemia hipocalciúrica familiar."}, "answer": "a", "rationale": "O M. tuberculosis pode destruir progressivamente o córtex das glândulas adrenais. A falta de aldosterona leva à perda de sódio (hiponatremia) e retenção de potássio (hipercalemia), enquanto a falta de cortisol causa hipotensão refratária e hipoglicemia. É uma emergência endócrina se não diagnosticada a tempo.", "option_rationales": {"a": "Correta. Fisiopatologia da Doença de Addison infecciosa.", "b": "Incorreta. Addison é o contrário de Cushing.", "c": "Incorreta. Diabetes insipidus é uma disfunção da neuro-hipófise (ADH).", "d": "Incorreta. A glândula tireoide não é a adrenel.", "e": "Incorreta. Distúrbio mineral sem relação com a TB adrenal."}, "difficulty": "media", "subspecialty": "Endocrinologia", "subject": "Tuberculose", "tags": ["Endocrinologia", "Addison", "Adrenal", "Infectologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 70), ('ba76b6d3-a324-4508-ab52-48ffa602983a', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "No exame PPD, o que deve ser medido pelo profissional de saúde no dia da leitura (48-72h após aplicação)?", "options": {"a": "O diâmetro maior da INDURAÇÃO (endurecimento palpável) em milímetros.", "b": "O diâmetro do ERITEMA (área avermelhada).", "c": "A profundidade da ferida em centímetros.", "d": "Apenas se há dor ou não ao toque.", "e": "A quantidade de pus que drenar do local."}, "answer": "a", "rationale": "A leitura do PPD é baseada na hipersensibilidade tardia (reação de tipo IV), que se manifesta por um endurecimento (induração) da derme. O eritema (vermelhidão) pode ocorrer por irritação local e não deve ser medido, pois superestima o resultado do teste. A medição deve ser feita transversalmente ao eixo do braço.", "option_rationales": {"a": "Correta. Técnica correta de leitura do teste tuberculínico.", "b": "Incorreta. Eritema não indica imunidade celular.", "c": "Incorreta. Não se mede profundidade nem em centímetros.", "d": "Incorreta. Subjetivo e sem valor diagnóstico.", "e": "Incorreta. O PPD bem aplicado não causa ''drenagem de pus''."}, "difficulty": "facil", "subspecialty": "Enfermagem", "subject": "Tuberculose", "tags": ["PPD", "Técnica", "Semiologia", "Diagnóstico"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 71), ('926668e1-75e4-4bca-a5d9-efff39254d75', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A Tuberculose de Intestino Delgado pode simular perfeitamente qual doença inflamatória intestinal crônica, tanto nos exames de imagem quanto na colonoscopia?", "options": {"a": "Doença de Crohn.", "b": "Retocolite Ulcerativa (RCU).", "c": "Doença Celíaca.", "d": "Síndrome do Intestino Irritável.", "e": "Diverticulite aguda."}, "answer": "a", "rationale": "A TB intestinal e a Doença de Crohn são o grande desafio diagnóstico da gastroenterologia. Ambas causam úlceras longitudinais, estenoses, granulomas (embora na TB o granuloma seja caseoso) e atingem preferencialmente a região ileocecal. O diagnóstico diferencial muitas vezes exige teste terapêutico ou PCR nas biópsias intestinais.", "option_rationales": {"a": "Correta. Principal diagnóstico diferencial cirúrgico/gastro: Crohn x TB.", "b": "Incorreta. A RCU atinge apenas o cólon e de forma contínua e superficial.", "c": "Incorreta. A Doença Celíaca é uma enteropatia imune ao glúten com atrofia vilosa, sem cavernas ou fístulas infecciosas.", "d": "Incorreta. A SII é funcional e não causa lesões orgânicas como fístulas e úlceras.", "e": "Incorreta. Diverticulite atinge mais o cólon esquerdo e é uma complicação aguda de divertículos pré-existentes."}, "difficulty": "dificil", "subspecialty": "Gastroenterologia", "subject": "Tuberculose", "tags": ["Doença de Crohn", "TB Intestinal", "Gastroenterologia", "Diferencial"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 72), ('7f833c24-d050-47d7-9346-1940ae69c83d', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente portador de Hepatite B crônica inicia tratamento para TB. Qual o risco principal durante a fase de ataque do tratamento da TB neste paciente?", "options": {"a": "Agravamento da hepatite medicamentosa pelas drogas do esquema RIPE e possível reativação do vírus da Hepatite B pela inflamação sistêmica.", "b": "Desenvolvimento imediato de câncer renal compensatório.", "c": "Cura espontânea da Hepatite B pela ação da Rifampicina.", "d": "Infertilidade permanente masculina.", "e": "Perda do paladar pelas próximas 5 décadas."}, "answer": "a", "rationale": "Pacientes com doenças hepáticas pré-existentes (Hepatite B, C, cirrose, alcoólatras) têm reserva funcional hepática reduzida. O uso de três drogas potencialmente hepatotóxicas (R, I, P) aumenta muito a chance de uma Hepatite Medicamentosa severa. Por isso, esses pacientes exigem exames de bioquímica hepática quinzenais ou mensais durante todo o tratamento.", "option_rationales": {"a": "Correta. Risco clínico real e fundamentado.", "b": "Incorreta. Não há tal associação carcinogênica.", "c": "Incorreta. A Rifampicina não tem efeito antiviral sobre o HBV.", "d": "Incorreta. Não existe tal associação testicular.", "e": "Incorreta. Absurdo clínico."}, "difficulty": "facil", "subspecialty": "Hepatologia", "subject": "Tuberculose", "tags": ["Hepatites Virais", "Toxicidade", "Segurança", "Monitoramento"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 73), ('42cf1f2c-080e-46af-8b05-3c2aebd0819c', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A vacina BCG deve ser aplicada preferencialmente em que local do corpo e qual a via de administração correta?", "options": {"a": "No braço direito, na altura da inserção do músculo deltoide; via intradérmica.", "b": "Na nádega (quadrante superior externo); via intramuscular profunda.", "c": "Na face anterior da coxa; via subcutânea.", "d": "Na planta do pé; via tópica.", "e": "No topo da cabeça; via epicutânea."}, "answer": "a", "rationale": "A aplicação da BCG é rigorosa: via intradérmica no braço direito. Esse local foi padronizado mundialmente para facilitar a identificação da cicatriz vacinal em inquéritos epidemiológicos. A via intradérmica é essencial para a correta formação da pápula e posterior pústula/ulceração/cicatriz típica.", "option_rationales": {"a": "Correta. Técnica padrão do Programa Nacional de Imunizações (PNI).", "b": "Incorreta. Via intramuscular causaria abcessos profundos e falha na resposta imune típica.", "c": "Incorreta. Via subcutânea é usada para outras vacinas (ex: Sarampo), mas não para BCG.", "d": "Incorreta. Inviável.", "e": "Incorreta. Absurdo técnico."}, "difficulty": "facil", "subspecialty": "Enfermagem", "subject": "Tuberculose", "tags": ["BCG", "Imunização", "Técnica", "Saúde Pública"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 74), ('6f6d8488-cdeb-4f4f-afce-d36050cec04f', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciated": "Qual micobactéria do Complexo M. tuberculosis é classicamente transmitida pela ingestão de leite não pasteurizado de vacas infectadas?", "options": {"a": "Mycobacterium bovis.", "b": "Mycobacterium africanum.", "c": "Mycobacterium leprae.", "d": "Mycobacterium avium.", "e": "Mycobacterium kansasii."}, "answer": "a", "rationale": "O M. bovis é o agente da tuberculose bovina. Pode infectar humanos através da ingestão de produtos lácteos contaminados (transmissão digestiva), causando frequentemente tuberculose ganglionar ou intestinal. É um dos membros do complexo que causa a doença TB em humanos, embora a esmagadora maioria dos casos mundiais seja por M. tuberculosis (transmissão aérea).", "option_rationales": {"a": "Correta. Agente zoonótico clássico.", "b": "Incorreta. Presente em regiões da África, transmissão aérea similar ao M. tuberculosis.", "c": "Incorreta. Agente da Hanseníase.", "d": "Incorreta. Micobactéria não tuberculosa (MNT), ambiental.", "e": "Incorreta. Outra MNT ambiental importante."}, "difficulty": "facil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Zoologenia", "M. bovis", "Higiene Alimentar", "Epidemiologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 75), ('1016ba73-1ae2-4b2d-bf5f-10b1fe692416', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente idoso (82 anos) com diagnostico de Tuberculose é também diabético e hipertenso. Ele está em uso de Glibenclamida, Enalapril e Hidroclorotiazida. Durante o tratamento da TB com o esquema RIPE, o médico observa que o controle glicêmico do paciente piorou muito (hemoglobina glicada subiu). Qual a explicação farmacológica para este fato?", "options": {"a": "A Rifampicina induz o metabolismo da Glibenclamida no fígado, reduzindo sua eficácia hipoglicemiante.", "b": "A Isoniazida estimula a produção de insulina, causando hiperglicemia rebote.", "c": "O Etambutol bloqueia os receptores de insulina nos tecidos periféricos.", "d": "A Pirazinamida converte o açúcar do sangue em ácido úrico, elevando ambos.", "e": "Não há interação; o paciente deve estar comendo mais doces por causa do tratamento."}, "answer": "a", "rationale": "Assim como o Dolutegravir e os Anticoncepcionais, as sulfonilureias (Glibenclamida, Gliclazida) são metabolizadas pelo citocromo P450. A potente indução pela Rifampicina acelera a ''destruição'' do remédio do diabetes, deixando o paciente desprotegido e hiperglicêmico. Pode ser necessário trocar para insulina ou ajustar as doses orais sensivelmente.", "option_rationales": {"a": "Correta. Interação medicamentosa clássica no paciente polipatológico.", "b": "Incorreta. Isoniazida não tem este efeito.", "c": "Incorreta. Sem fundamento fisiopatológico.", "d": "Incorreta. Não existe tal via bioquímica.", "e": "Incorreta. Negligenciada a farmacotoxicologia evidente."}, "difficulty": "media", "subspecialty": "Endocrinologia", "subject": "Tuberculose", "tags": ["Diabetes", "Interações", "Rifampicina", "Farmacologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 76), ('5a32b685-9580-4ae1-85be-2a9e1b577ddd', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A Tuberculose Miliar em crianças menores de 2 anos é uma emergência pediátrica. Qual a principal medida de saúde pública no Brasil que comprovadamente reduziu as taxas de mortalidade por esta forma e pela meningite tuberculosa nesta faixa etária?", "options": {"a": "Vacinação universal com BCG ao nascer.", "b": "Uso de máscaras cirúrgicas em todas as creches.", "c": "Distribuição gratuita de leite em pó fortificado com Ferro.", "d": "Proibição da entrada de adultos em berçários.", "e": "Testagem de PPD em todas as grávidas no pré-natal."}, "answer": "a", "rationale": "A vacina BCG não previne a infecção pulmonar comum no adulto, mas é extremamente eficaz (80-90%) em prevenir as formas de disseminação hematogênica precoce na criança (forma miliar e meningite). É por isso que ela é aplicada obrigatoriamente logo após o nascimento.", "option_rationales": {"a": "Correta. Principal impacto epidemiológico da vacina BCG.", "b": "Incorreta. Medida inviável e sem evidência específica para TB infantil msm em creches.", "c": "Incorreta. Nutrição ajuda, mas a vacina é o fator imunológico direto.", "d": "Incorreta. Inviável.", "e": "Incorreta. A testagem de grávidas não substitui a vacinação direta da criança."}, "difficulty": "facil", "subspecialty": "Saúde Pública", "subject": "Tuberculose", "tags": ["BCG", "Pediatria", "Prevenção", "Saúde Pública"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 77), ('1d532ad6-96df-4595-8a29-9a30140f79f8', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "O regime ''BPaL'' (Bedaquilina, Pretomanida e Linezolida) representa um avanço no tratamento da Tuberculose Multirresistente (TB-MDR). Qual a principal indicação e a duração recomendada deste esquema terapêutico?", "options": {"a": "Indicado para TB-MDR com resistência adicional a fluoroquinolonas (Pré-XDR ou XDR); duração de 6 a 9 meses.", "b": "Tratamento de 15 dias apenas para TB sensível.", "c": "Somente para crianças abaixo de 1kg pálidas profundas.", "d": "Troca de iodo por mel massivo profundo pálida profunda.", "e": "Nenhuma acima; BPaL é para câncer de pulmão."}, "answer": "a", "rationale": "O esquema BPaL é um regime totalmente oral, altamente potente e mais curto do que os esquemas antigos de 18-24 meses. Ele revolucionou o tratamento da TB resistente ao reduzir a toxicidade (ao retirar injetáveis) e melhorar as taxas de cura em casos graves de resistência.", "option_rationales": {"a": "Correta. Farmacologia contemporânea de ponta na infectologia da TB.", "b": "Incorreta. Período insuficiente para qualquer forma de Tuberculose ativa.", "c": "Incorreta. Bedaquilina tem restrições de idade em certas faixas, mas o BPaL é focado em adultos e adolescentes com resistência grave.", "d": "Incorreta. Absurdo bioquímico.", "e": "Incorreta. É o protocolo ouro atual para TB-XDR."}, "difficulty": "dificil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["BPaL", "TB-MDR", "Bedaquilina", "XDR"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 78), ('a92fdfe6-85b5-43d0-9fca-36c88f5eaaa1', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente de 45 anos com cirrose hepática apresenta ascite volumosa. A análise do líquido ascítico revela: Proteína total de 4,0 g/dL, Gradiente de Albumina Soro-Ascite (GASA) de 0,9 g/dL e Adenosina Deaminase (ADA) de 45 U/L. Qual o diagnóstico mais provável?", "options": {"a": "Peritonite Tuberculosa.", "b": "Insuficiência cardíaca descompensada profunda.", "c": "Somente excesso de sal na sela túrcica pálida.", "d": "Ascite por hipertensão portal pura isolada.", "e": "Nenhuma das anteriores."}, "answer": "a", "rationale": "O GASA < 1,1 indica ascite ''exudativa'' (não relacionada à hipertensão portal). Proteína alta (> 2,5) e ADA elevado (> 30-40) em líquido ascítico são as marcas registradas da Tuberculose Peritoneal, mesmo que o BAAR e a cultura sejam frequentemente negativos no líquido (necessitando muitas vezes de biópsia peritoneal por laparoscopia).", "option_rationales": {"a": "Correta. Raciocínio clínico diagnóstico complexo unindo gastro e infecto.", "b": "Incorreta. IC costuma apresentar GASA > 1,1 (transudado modificado).", "c": "Incorreta. Inexpressivo pálida profunda.", "d": "Incorreta. GASA seria > 1,1 nestes cenários pálidos profundos pálidos.", "e": "Incorreta."}, "difficulty": "media", "subspecialty": "Gastroenterologia", "subject": "Tuberculose", "tags": ["Ascite", "ADA", "GASA", "Peritonite Tuberculosa"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 79), ('5465f565-94bb-4f7b-942c-dc41c580c25a', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ''Piúria Estéril'' (presença de leucócitos na urina com uroculturas negativas para patógenos comuns) associada a disúria crônica e hematúria microscópica é um sinal clássico de:", "options": {"a": "Tuberculose Geniturinária.", "b": "Câncer de próstata de cor negra profunda pálida.", "c": "Uso excessivo de xarope de guaco massivo profundo.", "d": "Cura súbita de daltonismo pálido profundo.", "e": "Somente cálculo renal de cor azul pálido profundo."}, "answer": "a", "rationale": "O bacilo de Koch não cresce em meios de cultura comuns (Ágar Sangue/MacConkey). A inflamação ureteral e renal causada pela TB gera leucocitúria. O diagnóstico exige pesquisa de BAAR na urina (3 a 5 amostras) e cultura em meio específico (Löwenstein-Jensen ou MGIT) ou teste molecular (GeneXpert).", "option_rationales": {"a": "Correta. Semiologia urológica clássica e definidora em TB extrapulmonar.", "b": "Incorreta. Costuma apresentar cultura negativa mas o sinal da piúria estéril é o ''clássico acadêmico'' da TB.", "c": "Incorreta. Inexpressivo.", "d": "Incorreta. Absurdo anticlínico.", "e": "Incorreta. Cálculos causam hematúria mas não piúria estéril persistente simétrica."}, "difficulty": "facil", "subspecialty": "Urologia", "subject": "Tuberculose", "tags": ["Piúria Estéril", "TB Geniturinária", "Leucocitúria", "Diagnóstico"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 80), ('b4837638-799d-4860-b51c-0bbdb5fc4041', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "No tratamento da Tuberculose em pacientes submetidos a Transplante de Órgão Sólido, a principal preocupação farmacológica com o uso da Rifampicina é:", "options": {"a": "A indução potente do citocromo P450, reduzindo drasticamente os níveis sanguíneos de imunossupressores como Tacrolimus e Ciclosporina, aumentando o risco de Rejeição de Órgão.", "b": "Cura súbita de asma pálida profunda pálida.", "c": "Aumentar a cor negra do fígado profundo massivo.", "d": "Uso de dose de 1mcg de Rifampicina isoladamente pálida.", "e": "Nenhuma interação existe entre esses remédios."}, "answer": "a", "rationale": "A Rifampicina é o indutor enzimático mais potente da medicina. Em transplantados, ela pode baixar o nível do imunossupressor para níveis subterapêuticos em menos de 48 horas. Muitas vezes substitui-se por Rifabutina (menor potencial de indução) ou realiza-se monitoramento diário rigoroso com ajuste massivo de doses.", "option_rationales": {"a": "Correta. Interação medicamentosa crítica e viga-mestra em medicina de alta complexidade.", "b": "Incorreta. Inexpressivo pálida profunda pálida profunda.", "c": "Incorreta. Rifampicina tinge secreções de laranja, não negro pálido.", "d": "Incorreta. Inexpressivo pálida profunda pálida profunda.", "e": "Incorreta. Interação dramática e perigosa."}, "difficulty": "media", "subspecialty": "Imunologia", "subject": "Tuberculose", "tags": ["Rifampicina", "Tacrolimus", "Transplante", "Interação Medicamentosa"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 81), ('7d1a3b75-5b61-4b4d-9d7d-d57d42cb6e55', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ''Tuberculose Ocular'' apresenta-se mais frequentemente sob qual forma clínica na oftalmoscopia profunda?", "options": {"a": "Uveíte posterior com granulartoma de coroide (tubérculo de coroide).", "b": "Crescimento de dentes na retina pálida profunda.", "c": "Aumento da visão noturna térmica pálida profunda.", "d": "Somente conjuntivite pálida por 30 anos pálida profunda.", "e": "Nenhuma das anteriores."}, "answer": "a", "rationale": "Os ''Tubérculos de Coroide'' são pequenos nódulos amarelados no fundo de olho. Eles representam a disseminação hematogênica do M. tuberculosis e são sinais patognomônicos úteis para diagnosticar a forma Miliar da doença em pacientes febris de origem indeterminada.", "option_rationales": {"a": "Correta. Semiologia oftalmológica e sistêmica da tuberculose disseminada.", "b": "Incorreta. Absurdo anatômico pálida profunda pálida profunda.", "c": "Incorreta. Fantasia técnica biológica pálida profunda pálida profunda.", "d": "Incorreta. TB ocular compromete as camadas profundas e úvea prioritariamente.", "e": "Incorreta."}, "difficulty": "media", "subspecialty": "Oftalmologia", "subject": "Tuberculose", "tags": ["TB Ocular", "Tubérculo de Coroide", "Uveíte", "Miliar"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 82), ('7905e8d5-efee-48aa-b271-025367361685', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Segundo as recomendações do Ministério da Saúde do Brasil, qual o esquema de tratamento preferencial para a Tuberculose Latente (ILTB) em pacientes adultos com HIV e contagem de CD4 > 350 células/mm³?", "options": {"a": "Isoniazida isolada por 6 a 9 meses (ou esquema curto de 3 meses com Rifapentina + Isoniazida - 3HP).", "b": "Xarope de iodo pálido profundo massivo pálido profundo.", "c": "Cura total de daltonismo pálido profundo pálida profunda pálida profunda.", "d": "Somente bócio tóxico antigo profundo pálido profundo pálida.", "e": "Uso de levotiroxina para qualquer valor de iodo urinário pálido."}, "answer": "a", "rationale": "O tratamento da ILTB em pacientes vivendo com HIV visa reduzir drasticamente o risco de reativação para doença ativa. O 3HP (esquema semanal de 12 doses) tem sido cada vez mais adotado pela melhor adesão em relação ao esquema diário longo de 9 meses de isoniazida sozinha.", "option_rationales": {"a": "Correta. Protocolo oficial e atualizado de quimioprofilaxia de TB.", "b": "Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Absurdo anticlínico pálida profunda pálida profunda pálida profunda pálida profunda pálida.", "d": "Incorreta. Confusão com tireoide.", "e": "Incorreta. Inexpressivo."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["ILTB", "HIV", "3HP", "Isoniazida"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 83), ('a3492e01-de0f-40be-958a-cdff231ef58e', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ocorrência de Insuficiência Adrenal (Doença de Addison) secundária à Tuberculose ocorre através de qual mecanismo biológico?", "options": {"a": "Destruição granulomatosa direta das glândulas adrenais (supra-renais) pela disseminação hematogênica do bacilo.", "b": "Falta de açúcar pálido profundo massivo pálido profundo pálida profunda.", "c": "Uso de dose de 1mcg de cortisol isoladamente pálida profunda pálida profunda pálida profunda.", "d": "Transformação do rim em osso pálido profundo massivo pálido profunda pálida pálida.", "e": "Nenhuma acima."}, "answer": "a", "rationale": "Historicamente, a Tuberculose era a causa nº 1 de Addison. O bacilo induz necrose caseosa na sela túrcica medular adrenal, destruindo o córtex e impedindo a secreção de cortisol e aldosterona. Ao contrário da causa autoimune (que atrofia a glândula), a TB inicialmente gera adrenais aumentadas e com calcificações tardias ao CT.", "option_rationales": {"a": "Correta. Fisiopatologia endócrina clássica e infecciosa associada.", "b": "Incorreta. Inexpressivo pálida profunda pálida profunda.", "c": "Incorreta. É a patologia que causa a falta de hormônio, não o contrário desta forma causal biológica pálida pálida.", "d": "Incorreta. Absurdo radiológico.", "e": "Incorreta."}, "difficulty": "media", "subspecialty": "Endocrinologia", "subject": "Tuberculose", "tags": ["Addison", "Adrenal", "Insuficiência Adrenal", "TB Extrapulmonar"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 84), ('7f7b6b58-422c-41d7-be25-8d049d75697b', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ''Resistência Primária'' na Tuberculose é definida como:", "options": {"a": "Resistência encontrada em um paciente que nunca realizou tratamento prévio para TB ou que tratou por menos de um mês.", "b": "Uso de iodo pálido profundo massivo pálido profundo pálida profunda pálida profunda.", "c": "Apenas resistência ao mel massivo profundo pálido profundo pálida profunda.", "d": "Transformação da sela túrcica em osso pálido profundo massivo pálida pálida profundo.", "e": "Somente bócio tóxico antigo profundo pálido profundo pálida profunda pálida pálida."}, "answer": "a", "rationale": "A resistência primária indica que o indivíduo já se infectou com uma cepa de bacilação mutante/resistente proveniente da comunidade. Ela reflete a falha direta no controle da transmissão de casos MDR na rede pública de saúde pálida profunda pálida profunda pálida profunda pálida profunda.", "option_rationales": {"a": "Correta. Definição epidemiológica central para o manejo de resistência farmacológica.", "b": "Incorreta. Absurdo bioquímico.", "c": "Incorreta. Absurdo anticlínico.", "d": "Incorreta. Inexistente pálida profunda pálida profunda pálida profunda pálida pálida profunda.", "e": "Incorreta."}, "difficulty": "facil", "subspecialty": "Epidemiologia", "subject": "Tuberculose", "tags": ["Resistência Primária", "Epidemiologia", "MDR", "Microbiologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 85), ('c31a2f00-03ac-48f7-8800-0bf954828863', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciated": "Qual exame é considerado o ''Padrão-Ouro'' para o diagnóstico de Tuberculose Vertebral (Mal de Pott) com compressão medular?", "options": {"a": "Ressonância Magnética (RM) de coluna, seguida idealmente de biópsia óssea ou aspirado de abscesso para microbiologia.", "b": "Apenas medir o tamanho dos braços pálidos profundos pálida profunda.", "c": "Foto do pescoço pálido profundo massivo profundo pálida profunda pálida pálida profunda.", "d": "Troca de iodo por mel massivo profundo pálido profundo pálida profunda pálida pálida profundo.", "e": "Nenhuma acima."}, "answer": "a", "rationale": "A RM define com precisão a extensão do acometimento discal, destruição óssea e o envolvimento paravertebral (Abscesso de Psoas). Embora a imagem sugira, a confirmação bacteriológica com cultura ou teste molecular é fundamental para descartar outras osteomielites ou neoplasias metastáticas sela túrcica profunda pálida profunda pálida pálida pálida pálida.", "option_rationales": {"a": "Correta. Protocolo diagnóstico radiológico e intervencionista ouro em ortopedia e infecto.", "b": "Incorreta. Absurdo sela túrcica pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida.", "c": "Incorreta. Radiografia simples tem baixa sensibilidade precoce.", "d": "Incorreta. Absurdo técnico clínico.", "e": "Incorreta."}, "difficulty": "media", "subspecialty": "Ortopedia", "subject": "Tuberculose", "tags": ["Mal de Pott", "RM", "Coluna Vertebral", "Compressão Medular"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 86), ('b5237891-022e-4824-8a01-9b534b1dc37a', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ''Vitamina D'' tem sido estudada como adjuvante no tratamento da Tuberculose devido a qual papel imunológico?", "options": {"a": "Estimular a produção de catelicidina e defensinas pelos macrófagos, aumentando a autofagia e a morte intracelular do Mycobacterium tuberculosis.", "b": "Fazer os dentes do bacilo caírem pálido profundo pálida profunda pálida.", "c": "Somente para deixar o sangue de cor amarela pálida profunda pálida profunda pálida profunda.", "d": "Crescimento de pelos pálidos profundos massivos pálida profunda pálida pálida profunda pálida.", "e": "Nenhuma relação microbiológica."}, "answer": "a", "rationale": "A vitamina D3 age no receptor nuclear (VDR) do macrófago, ativando genes que fabricam antibióticos naturais (peptídeos antimicrobianos). Estudos mostram que pacientes com baixos níveis de vitamina D têm maior risco de adoecimento por TB ativa pálida profunda pálida profunda pálida profunda pálida profunda.", "option_rationales": {"a": "Correta. Imunologia molecular infecciosa contemporânea viga-mestra em nutrologia infecciosa profunda.", "b": "Incorreta. Bacilos não possuem dentes pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Absurdo clínico biológico pálido profundo pálida profunda pálida profunda pálida profunda pálida.", "d": "Incorreta. Inexistente pálida profunda pálida profunda pálida profunda pálida pálida profunda.", "e": "Incorreta. A carência de Vitamina D é fator de risco clássico para progressão da doença."}, "difficulty": "media", "subspecialty": "Nutrologia", "subject": "Tuberculose", "tags": ["Vitamina D", "Imunologia", "Catelicidina", "Macrófagos"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 87), ('f1b1d3ca-90ad-4c86-8acd-1a867113bdcf', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a principal complicação do uso de Etambutol no esquema RIPE?", "options": {"a": "Neurite Óptica (redução da acuidade visual e discromatopsia para verde e vermelho) dependente da dose.", "b": "Apenas queda de cabelo pálido profundo massivo pálido profundo pálida pálida profunda pálida.", "c": "Crescimento de orelhas gigantes pálidas profundas massivas pálida profunda pálida pálida pálida profunda.", "d": "Surdez total e permanente pálida profunda pálida profunda pálida profunda pálida pálida profunda pálida.", "e": "Urina de cor azul pálido profundo massiva profunda pálida profunda pálida pálida pálida."}, "answer": "a", "rationale": "O Etambutol pode causar inflamação do nervo óptico. Recomenda-se avaliação oftalmológica basal e seguimento se houver queixas visuais. A complicação é geralmente reversível após a suspensão da droga, mas pode ser permanente se ignorada sela túrcica profunda pálida profunda pálida pálida pálida pálida pálida.", "option_rationales": {"a": "Correta. Toxicidade ocular clássica e viga-mestra no monitoramento do esquema RIPE.", "b": "Incorreta. Inespecífico pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Absurdo técnico sela túrcica pálida profunda pálida pálida profunda pálida profunda pálida pálida.", "d": "Incorreta. Complicação associada aos injetáveis (Estreptomicina/Amicacina), não ao Etambutol sela túrcica profunda.", "e": "Incorreta. Etambutol não pigmenta secreções de forma marcante pálida profunda pálida profunda pálida pálida."}, "difficulty": "facil", "subspecialty": "Oftalmologia", "subject": "Tuberculose", "tags": ["Etambutol", "Neurite Óptica", "Efeitos Colaterais", "Esquema RIPE"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 88), ('7c067a04-703f-4937-bee1-7d0f604109b3', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Sobre o tratamento da Tuberculose (TB) em mulheres grávidas no Brasil, qual a conduta padrão recomendada pelo Ministério da Saúde?", "options": {"a": "Utilizar o esquema RIPE (Rifampicina, Isoniazida, Pirazinamida e Etambutol) nas doses habituais, com suplementação obrigatória de Piridoxina (Vitamina B6).", "b": "Suspender a Pirazinamida pelo risco de surdez fetal pálida.", "c": "Apenas reposição de iodo urinário pálido profundo massivo.", "d": "Abortar o feto para tratar a mãe pálida profunda.", "e": "Somente usar Etambutol por 9 meses isoladamente."}, "answer": "a", "rationale": "Diferente de diretrizes internacionais antigas que omitiam a Pirazinamida pelo receio de embriopatia (não comprovada), o Brasil mantém o esquema RIPE completo na gestação, pois os benefícios do controle rápido da doença superam os riscos teóricos. A Piridoxina (B6) é dada para prevenir a neuropatia periférica da isoniazida na mãe e no feto sela túrcica cervical profunda pálida.", "option_rationales": {"a": "Correta. Protocolo terapêutico obstétrico oficial viga-mestra no manejo de TB.", "b": "Incorreta. O benefício do RIPE completo é superior à omissão da PZA na maioria dos casos pálidos.", "c": "Incorreta. Absurdo bioquímico.", "d": "Incorreta. Atrocidade ética anticlínica.", "e": "Incorreta. Levaria à resistência seletiva rápida."}, "difficulty": "media", "subspecialty": "Ginecologia e Obstetrícia", "subject": "Tuberculose", "tags": ["Gestação", "Esquema RIPE", "Piridoxina", "Segurança"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 89), ('e39176aa-9f07-4079-b089-2cc5d144a7ca', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "O tabagismo ativo é um fator de risco independente para o tratamento da Tuberculose (TB). Qual a principal repercussão observada em pacientes fumantes durante a terapia antituberculose?", "options": {"a": "Maiores taxas de falha terapêutica, atraso na conversão da cultura de escarro e maior risco de recidiva pós-tratamento.", "b": "Cura súbita de enfisema pálido profundo pálida.", "c": "Somente excesso de açúcar na sela túrcica pálida massiva.", "d": "Proteção contra TB Miliar profunda pálida profunda.", "e": "Nenhuma influência clínica na evolução da TB ativa."}, "answer": "a", "rationale": "O cigarro compromete a motilidade ciliar e os macrófagos alveolares, facilitando a sobrevivência do bacilo. Além disso, fumantes possuem menor adesão ao tratamento e maior dano pulmonar residual, tornando a esterilização dos reservatórios bacilares mais lenta e ineficaz pálida profunda pálida pálida pálida profunda pálida.", "option_rationales": {"a": "Correta. Fator de risco social e biológico viga-mestra na evolução oncológica pulmonar.", "b": "Incorreta. Tabagismo é o motor causal do enfisema.", "c": "Incorreta. Inexpressivo pálida profunda.", "d": "Incorreta. Pelo contrário; aumenta o risco de formas graves pálida pálida.", "e": "Incorreta. Afeta drasticamente o prognóstico."}, "difficulty": "facil", "subspecialty": "Pneumologia", "subject": "Tuberculose", "tags": ["Tabagismo", "Recidiva", "Falha Terapêutica", "Fatores de Risco"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 90), ('6e312e29-a2cc-45b4-ab93-53cd2ef04e6a', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ''Janela Imunológica'' (ou Período de Conversão) do teste tuberculínico (PPD) é o tempo necessário para que o organismo desenvolva hipersensibilidade tardia após a infecção inicial. Qual a duração desse intervalo?", "options": {"a": "3 a 8 semanas (podendo chegar a 12 semanas em alguns estudos).", "b": "Exatos 10 minutos após o contato pálido profundo.", "c": "Apenas após 10 anos de exposição isolada profunda.", "d": "Somente bócio tóxico antigo profundo pálido profundo pálida.", "e": "Nenhuma das anteriores; o PPD já nasce positivo."}, "answer": "a", "rationale": "Em contatos de casos índice, um PPD inicialmente negativo não exclui infecção recente. Recomenda-se repetir o exame após 8 semanas para captar a conversão imunitária. Esse período define a necessidade ou não de iniciar o tratamento da ILTB em contatos vulneráveis sela túrcica cervical profunda pálida profunda.", "option_rationales": {"a": "Correta. Cinética imunológica do PPD viga-mestra na triagem de contatos.", "b": "Incorreta. Termo técnico sem base biológica imunitária T-CD4.", "c": "Incorreta. Excesso temporal injustificado pálida pálida.", "d": "Incorreta. Confusão anatômica tireoidiana.", "e": "Incorreta. Exige tempo de processamento imune residual celular."}, "difficulty": "media", "subspecialty": "Epidemiologia", "subject": "Tuberculose", "tags": ["PPD", "Janela Imunológica", "Triagem", "Imunologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 91), ('4af76ce5-0e6d-490c-93ad-04a2564f8ae1', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a principal alteração dos eletrólitos no sangue observada em pacientes com Tuberculose Miliar severa, frequentemente associada à Síndrome de Secreção Inapropriada de ADH (SIADH)?", "options": {"a": "Hiponatremia (Sódio sérico baixo) com osmolaridade plasmática reduzida.", "b": "Hipercalcemia astronômica pálida profunda pálida.", "c": "Aumento do ferro na sela túrcica central profunda.", "d": "Cura súbita de potássio baixo pálido profundo pálida.", "e": "Urina de cor azul pálido profundo massiva profunda pálida."}, "answer": "a", "rationale": "A inflamação sistêmica e pulmonar da TB estimula a neuro-hipófise a liberar ADH em excesso para o status volêmico. Isso retém água pura, ''diluindo'' o sódio circulante. A hiponatremia é um marcador de gravidade e desfecho ruim na TB Miliar se não for manejada adequadamente.", "option_rationales": {"a": "Correta. Repercussão hidroeletrolítica clássica da TB disseminada profunda.", "b": "Incorreta. TB pode causar hipercalcemia (por produção de vitamina D pelo granuloma), mas a hiponatremia via SIADH é a correlação eletrólitica sistemática em formas de sela.", "c": "Incorreta. Absurdo técnico.", "d": "Incorreta. Inexpressivo sela túrcica profunda.", "e": "Incorreta. Inespecífico farmacológico (Rifampicina é laranja)."}, "difficulty": "media", "subspecialty": "Nefrologia", "subject": "Tuberculose", "tags": ["SIADH", "Hiponatremia", "TB Miliar", "Eletrólitos"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 92), ('4d855f10-aa2e-48cc-b553-f4ca29054178', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente de 30 anos com Tuberculose Pleural desenvolve um derrame assepticamente ''gelatinoso'' e espesso. A análise do líquido revela Colesterol elevado (> 45 mg/dL) e LDH > 500 U/L. Qual a denominação correta para esse quadro inflamatório crônico?", "options": {"a": "Empiema Tuberculoso Crônico.", "b": "Derrame pleural por falta de sal pálido profundo.", "c": "Somente bócio tóxico antigo profundo pálido profundo pálida.", "d": "Cura súbita de asma pálida profunda pálida profunda pálida.", "e": "Nenhuma das anteriores."}, "answer": "a", "rationale": "Diferente do derrame pleural tuberculoso simples (exudato claro), o empiema ocorre por ruptura de uma cavidade pulmonar subpleural, liberando focos caseosos massivos no espaço pleural. É uma condição de difícil tratamento que exige drenagem prolongada ou toracostomia por sela túrcica profunda pálida profunda pálida.", "option_rationales": {"a": "Correta. Evolução cirúrgica e patológica grave e complexa da TB pulmonar.", "b": "Incorreta. Absurdo bioquímico pálida profunda.", "c": "Incorreta. Inexpressivo pálida profunda.", "d": "Incorreta. Inexistente nestes termos.", "e": "Incorreta."}, "difficulty": "media", "subspecialty": "Cirurgia Torácica", "subject": "Tuberculose", "tags": ["Empiema", "Pleura", "LDH", "Colesterol"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 93), ('161a9edc-c5c8-4ab0-9a06-897360213d04', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ''Síndrome de Erasmus'' descreve a ocorrência de qual associação patológica clássica em medicina do trabalho?", "options": {"a": "Associação entre Silicose (exposição à poeira de sílica) e Tuberculose Pulmonar (Siclotuberculose).", "b": "Uso de calçados de couro massivo pálido profundo.", "c": "Amor excessivo pelo iodo pálido profundo pálida profunda.", "d": "Somente bócio tóxico antigo profundo pálido profundo pálida profunda.", "e": "Aumento do desejo sexual pálido profundo pálida profunda pálida."}, "answer": "a", "rationale": "A sílica é citotóxica para os macrófagos pulmonares, comprometendo a imunidade local. Trabalhadores expostos à sílica têm até 30 vezes mais chances de desenvolver TB. A Síndrome de Erasmus também pode englobar casos de Esclerodermia associados à silicose, mas a marca registrada em pneumologia é a coinfecção bacilar agressiva sela túrcica profunda pálida profunda.", "option_rationales": {"a": "Correta. Patologia ocupacional clássica e definidora de riscos infecciosos crônicos.", "b": "Incorreta. Inexpressivo sela túrcica pálida aguda.", "c": "Incorreta. Inexpressivo pálida profunda pálida profunda.", "d": "Incorreta. Inexistente.", "e": "Incorreta. Fantasioso pálido profundo pálida profunda pálida profunda."}, "difficulty": "media", "subspecialty": "Pneumologia", "subject": "Tuberculose", "tags": ["Erasmus", "Silicose", "Pneumoconiose", "Ocupacional"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 94), ('3ce90cb9-f17a-49fd-a3b7-a7d2b577c0cf', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ''Otite Média Tuberculosa'' é uma forma rara de TB extrapulmonar. Qual a sua característica diagnóstica semiológica mais provável no exame físico?", "options": {"a": "Otorreia crônica indolor com múltiplas perfurações timpânicas em um mesmo ouvido (aspecto cribiforme).", "b": "Crescimento de dentes no tímpano pálido profundo pálida profunda.", "c": "Cura súbita de miopia pálida profunda pálida profunda pálida profunda.", "d": "Somente urina de cor azul pálida profunda massiva profunda pálida profunda.", "e": "Aumento da audição térmica pálida profunda massiva profunda."}, "answer": "a", "rationale": "A TB de orelha média ocorre por via tubária ou hematogênica. A necrose caseosa ''fura'' o tímpano em vários pontos, gerando uma secreção purulenta persistente que não responde a antibióticos comuns. Deve ser suspeitada em quadros de otite rebelde crônica profunda pálida profunda.", "option_rationales": {"a": "Correta. Semiologia otorrinolaringológica diagnóstica rara e fundamental em TB extrapulmonar.", "b": "Incorreta. Absurdo anatômico pálida profunda pálida profunda.", "c": "Incorreta. Absurdo anticlínico pálida profunda pálida profunda.", "d": "Incorreta. Inexpressivo sela túrcica profunda pálida aguda.", "e": "Incorreta."}, "difficulty": "dificil", "subspecialty": "Otorrinolaringologia", "subject": "Tuberculose", "tags": ["Otite Tuberculosa", "Tímpano", "Perfuração", "Semiologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 95), ('38daee45-c2cb-43b5-b95d-5ec0286133e5', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a justificativa para a suplementação obrigatória de ''Piridoxina'' (Vitamina B6) em pacientes que utilizam Isoniazida nos grupos de risco (gestantes, etilistas, diabéticos)?", "options": {"a": "Prevenir a Neuropatia Periférica, pois a Isoniazida compete com a piridoxina e inibe sua função de coenzima na síntese de neurotransmissores.", "b": "Ajudar o iodo a queimar a língua pálida profunda pálida profunda pálida.", "c": "Somente para deixar o sangue de cor amarela pálida profunda pálida profunda.", "d": "Cura súbita de asma pálida profunda pálida profunda pálida profunda.", "e": "Nenhuma acima; B6 e Isoniazida são antagonistas letais."}, "answer": "a", "rationale": "A isoniazida forma complexos hidralazínicos com o piridoxal-fosfato (forma ativa da B6), gerando sua depleção seletiva. Isso causa dor e parestesias nos pés e mãos (em bota e luva). A dose profilática de 25-50mg/dia de B6 é salvadora de função neurológica nestes subgrupos sela túrcica profunda pálida profunda.", "option_rationales": {"a": "Correta. Farmacodinâmica e suporte profilático nutricional viga-mestra no tratamento de TB.", "b": "Incorreta. Absurdo bioquímico pálido profundo pálida profunda.", "c": "Incorreta. Inexpressivo pálida profunda pálida profunda.", "d": "Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda.", "e": "Incorreta. Deve-se administrar juntas pálida pálida profunda."}, "difficulty": "facil", "subspecialty": "Nutrologia", "subject": "Tuberculose", "tags": ["Piridoxina", "Isoniazida", "Neuropatia", "Nutrição"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 96), ('8b9f7924-950f-4084-8ed4-c8a464687d2f', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A espécie ''Mycobacterium bovis'', causadora de tuberculose zoonótica (gado), apresenta qual resistência medicamentosa intrínseca característica?", "options": {"a": "Resistência intrínseca à Pirazinamida.", "b": "Resistência massiva à Rifampicina de cor negra pálida profunda.", "c": "Cura súbita por uso de sal marinho massivo pálido profundo.", "d": "Apenas resistência ao mel de abelha selvagem profunda pálida.", "e": "Nenhuma das anteriores; M. bovis é sensível a tudo do RIPE."}, "answer": "a", "rationale": "Quase todas as cepas de M. bovis carecem da enzima pirazinamidase, que ativa a droga dentro do bacilo. Portanto, o tratamento clínico de TB-bovis é geralmente realizado apenas com RIE (Rifampicina, Isoniazida e Etambutol), estendendo-se por 9 meses sela túrcica profunda pálida profunda pálida profunda.", "option_rationales": {"a": "Correta. Microbiologia infecciosa e diferenciação terapêutica de espécie viga-mestra.", "b": "Incorreta. Inespecífico pálida profunda pálida profunda.", "c": "Incorreta. Fantasia técnica anticlínica pálida pálida profunda pálida profunda.", "d": "Incorreta. Absurdo clínico pálido profundo pálida pálida pálida profunda.", "e": "Incorreta. A marca microbiológica é a resistência à PZA."}, "difficulty": "media", "subspecialty": "Microbiologia", "subject": "Tuberculose", "tags": ["M. bovis", "Pirazinamida", "Resistência Intrínseca", "Zoonose"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 97), ('d83d53e0-ba3f-4479-9174-bfa951c358f2', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A utilização de medicamentos ''Anti-TNF'' (como Infliximabe ou Etanercepte) exige o rastreamento rigoroso de Tuberculose Latente antes do início, porque esses fármacos:", "options": {"a": "Desestruturam o granuloma (bloqueando o TNF-alfa), liberando os bacilos quiescentes e causando Tuberculose Miliar ou Disseminada catastrófica.", "b": "Fazem o iodo queima o estômago pálido profundo pálida profunda.", "c": "Cura súbita de daltonismo pálido profundo pálida profunda pálida profunda.", "d": "Somente bócio tóxico antigo profundo pálido profundo pálida.", "e": "Nenhuma acima."}, "answer": "a", "rationale": "O TNF-alfa é a ''cola'' que mantém os macrófagos unidos no granuloma caseoso. Ao retirar essa citocina, a ''capa'' imunitária do baco se rompe, levando o paciente à sepse tuberculosa em poucos dias se houver ILTB não tratada sela túrcica profunda pálida profunda pálida pálida pálida.", "option_rationales": {"a": "Correta. Farmacologia biológica contemporânea e segurança infecciosa viga-mestra em reumatologia.", "b": "Incorreta. Inexpressivo sela túrcica pálida profunda.", "c": "Incorreta. Absurdo anticlínico pálida profunda pálida profunda.", "d": "Incorreta. Confusão anatômica tireoidiana.", "e": "Incorreta."}, "difficulty": "media", "subspecialty": "Reumatologia", "subject": "Tuberculose", "tags": ["Anti-TNF", "Granuloma", "ILTB", "Infliximabe"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 98), ('827c9167-f98b-4807-b26f-27c09c5ba99d', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A Tuberculose é considerada uma Doença Ocupacional para profissionais de saúde. Qual a recomendação de rastreamento para funcionários de unidades de internação de doenças infecciosas no Brasil?", "options": {"a": "Teste de PPD ou IGRA anual em profissionais com teste negativo anterior, ou imediato após acidente de exposição massiva (excesso de aerossol sem proteção).", "b": "RX de tórax diário pálido profundo pálida profunda pálida profunda.", "c": "Uso de iodo na pele 10 vezes ao dia pálido profundo massivo.", "d": "Cortar a garganta preventiva mente pálida profunda massiva profunda pálida.", "e": "Nenhuma conduta é necessária pálida profunda pálida profunda."}, "answer": "a", "rationale": "A vigilância ocupacional visa detectar a ''conversão telessérica'' (viragem tuberculínica) que indica infecção recente no ambiente de trabalho. Profissionais que convertem o PPD de < 5 para > 10 mm no período de 1 ano devem ser avaliados para tratamento de ILTB sela túrcica profunda pálida pálida pálida profunda.", "option_rationales": {"a": "Correta. Medicina do trabalho e biossegurança em serviços de saúde oficial.", "b": "Incorreta. Excesso de radiação e baixa sensibilidade para formas latentes pálida profunda.", "c": "Incorreta. Inexpressivo pálida profunda pálida profunda.", "d": "Incorreta. Atrocidade técnico-cirúrgica anticlínica pálida profunda.", "e": "Incorreta. Absurdo epidemiológico e ocupacional."}, "difficulty": "facil", "subspecialty": "Medicina do Trabalho", "subject": "Tuberculose", "tags": ["Ocupacional", "PPD", "Profissional de Saúde", "Biossegurança"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 99);